import {element as el,number,date,radar} from './portal-ui.js';
export function printReport(data){
 document.querySelector('#technical-report')?.remove();const report=el('section');report.id='technical-report';report.append(el('h1','Musuroom — Báo cáo cảm quan'),el('p',`Đợt ${data.session_code} · Mẫu ${data.sample_code} · ${data.count} phiếu`),el('p',`Xuất lúc ${date(new Date().toISOString())} · Thang ưa thích 1–9`));const chart=el('div','','report-chart');radar(chart,data.radar.values,data.radar.labels);report.append(chart);
 const table=el('table'),head=el('tr');for(const label of ['Tiêu chí','Trung bình','Trung vị','SD mẫu','Số phiếu'])head.append(el('th',label));table.append(head);Object.values(data.metrics).forEach((m,i)=>{const row=el('tr');for(const value of [data.radar.labels[i],number(m.mean),number(m.median),number(m.sd),m.n])row.append(el('td',value));table.append(row);});report.append(table,el('p','SD mẫu dùng mẫu số n−1; không tính khi có dưới 2 phiếu. Đây là thống kê mô tả của các phiếu đã tiếp nhận, không chứng minh độ an toàn, đại diện thị trường hoặc khác biệt có ý nghĩa thống kê.'),el('p','Nguồn: dữ liệu khảo sát của Musuroom, phân nhóm theo mã đợt và mẫu. Không chứa tên, liên hệ hoặc nhận xét thô.'));document.body.append(report);document.body.classList.add('reporting');window.addEventListener('afterprint',()=>{document.body.classList.remove('reporting');report.remove();},{once:true});window.print();
}
